with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Value returned from setTimeout goes nowhere$$,
    $$javascript$$,
    $$async_race_condition$$,
    $$medium$$,
    $$doubleLater$$,
    $$function doubleLater(value) {
    setTimeout(() => {
        return value * 2;
    }, 1);
}$$,
    $$function doubleLater(value) {
    return new Promise((resolve) => {
        setTimeout(() => {
            resolve(value * 2);
        }, 1);
    });
}$$,
    $$doubleLater(value) should resolve to double the value after a short delay, so doubleLater(4) gives 8.$$,
    $$doubleLater(4) returns undefined instead of 8.$$,
    $$The return statement belongs to the arrow function passed to setTimeout, not to doubleLater. doubleLater itself falls off the end and returns undefined immediately — long before the timer even fires. A value produced later can only be handed back through a promise (or a callback). Wrapping the timer in `new Promise` and calling resolve gives the caller something to await. Returning from inside a callback and expecting it to escape the outer function is one of the most common early async mistakes.$$,
    $$[{"input":[4],"expected_output":8},{"input":[0],"expected_output":0},{"input":[-3],"expected_output":-6}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$Which function does that `return` actually belong to?$$ from new_challenge
union all
select id, 2, $$doubleLater finishes before the timer fires. What can it hand back in the meantime?$$ from new_challenge
union all
select id, 3, $$Wrap the setTimeout in new Promise and call resolve(value * 2) instead of returning.$$ from new_challenge;

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Cache stampede loads the config twice$$,
    $$javascript$$,
    $$async_race_condition$$,
    $$hard$$,
    $$countLoads$$,
    $$async function countLoads(callCount) {
    let loads = 0;
    let cache = null;

    const getConfig = async () => {
        if (!cache) {
            loads = loads + 1;
            await new Promise((r) => setTimeout(r, 5));
            cache = { ready: true };
        }
        return cache;
    };

    const calls = [];
    for (let i = 0; i < callCount; i++) calls.push(getConfig());
    await Promise.all(calls);
    return loads;
}$$,
    $$async function countLoads(callCount) {
    let loads = 0;
    let cache = null;

    const getConfig = () => {
        if (!cache) {
            cache = (async () => {
                loads = loads + 1;
                await new Promise((r) => setTimeout(r, 5));
                return { ready: true };
            })();
        }
        return cache;
    };

    const calls = [];
    for (let i = 0; i < callCount; i++) calls.push(getConfig());
    await Promise.all(calls);
    return loads;
}$$,
    $$countLoads(n) makes n concurrent calls to a cached loader and returns how many times the expensive load actually ran. It should always be 1.$$,
    $$countLoads(3) returns 3 — the cache does nothing when the calls overlap, though countLoads(1) correctly returns 1.$$,
    $$The cache is only populated AFTER the await, so every caller that arrives during the in-flight load still sees `cache` as null and starts its own. This is a cache stampede, and it is invisible in sequential tests — it only appears under concurrency. The fix is to cache the PROMISE rather than the resolved value, and to do it synchronously before any await. Later callers then get the same in-flight promise and wait on the one load already running. The same pattern applies to any deduplicated async work: memoise the promise, not the result.$$,
    $$[{"input":[3],"expected_output":1},{"input":[1],"expected_output":1},{"input":[5],"expected_output":1}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$Sequential calls work; concurrent ones don't. What is different about the timing?$$ from new_challenge
union all
select id, 2, $$When does `cache` actually get set, relative to the await?$$ from new_challenge
union all
select id, 3, $$Store the promise in the cache synchronously, before awaiting, so overlapping callers share it.$$ from new_challenge;

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
