with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Overbooking when everyone checks at once$$,
    $$javascript$$,
    $$async_race_condition$$,
    $$hard$$,
    $$bookSeats$$,
    $$async function bookSeats(requests) {
    let seatsLeft = 1;
    let booked = 0;

    const attempts = [];
    for (let i = 0; i < requests; i++) {
        attempts.push(
            (async () => {
                if (seatsLeft > 0) {
                    await new Promise((r) => setTimeout(r, 5));
                    seatsLeft = seatsLeft - 1;
                    booked = booked + 1;
                }
            })()
        );
    }
    await Promise.all(attempts);
    return booked;
}$$,
    $$async function bookSeats(requests) {
    let seatsLeft = 1;
    let booked = 0;

    const attempts = [];
    for (let i = 0; i < requests; i++) {
        attempts.push(
            (async () => {
                if (seatsLeft > 0) {
                    seatsLeft = seatsLeft - 1;
                    booked = booked + 1;
                    await new Promise((r) => setTimeout(r, 5));
                }
            })()
        );
    }
    await Promise.all(attempts);
    return booked;
}$$,
    $$bookSeats(n) handles n concurrent booking requests for a single remaining seat and returns how many bookings succeeded. It should never exceed 1.$$,
    $$bookSeats(3) returns 3 — three people booked the same single seat. bookSeats(1) correctly returns 1, so the bug only shows up under load.$$,
    $$This is a time-of-check to time-of-use (TOCTOU) race. Every request checks `seatsLeft > 0` and then awaits BEFORE decrementing, so all of them pass the check while the seat is still nominally available and only then start taking it. The check and the act must not be separated by a suspension point: decrementing before the await makes the seat unavailable to everyone who checks afterwards. This is the shape of real overbooking, double-spend and duplicate-signup bugs — and note that it is invisible to a single-user test, which is why concurrency needs its own test cases.$$,
    $$[{"input":[3],"expected_output":1},{"input":[1],"expected_output":1},{"input":[5],"expected_output":1}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$One request works fine; three do not. What do the three have in common?$$ from new_challenge
union all
select id, 2, $$Between checking seatsLeft and changing it, what else gets a chance to run?$$ from new_challenge
union all
select id, 3, $$Decrement seatsLeft before the await, so the check and the booking cannot be interleaved.$$ from new_challenge;
